package mediatest

import "encoding/base64"

// The fixtures below are synthetic solid-color, single-frame videos generated
// from FFmpeg 9.0.1's public lavfi color source. Generation used no external
// input, and every result was decoded back to a null sink before its base64 was
// recorded. Tests decode these constants directly and require no codec binary.

// H264MOV returns a 16x16 red H.264 QuickTime fixture. SHA-256:
// d6d619c2ff67a1216d81ec675cc61c14d70e88bd11c6514d04a1f0414960b1ee
//
// ffmpeg -f lavfi -i color=c=red:s=16x16:r=1:d=1 -frames:v 1 -an
// -c:v libx264 -pix_fmt yuv420p -preset veryslow -tune stillimage
// -bsf:v filter_units=remove_types=6 -map_metadata -1 -movflags +faststart
// -f mov h264.mov.
func H264MOV() []byte {
	return decodeFixture(h264MOVBase64)
}

// H265MP4 returns a 16x16 green H.265 MP4 fixture. SHA-256:
// 5d7367612c8bf7f9688722fde62718eb404986c6503d01bd9727a3e7fb30ee4b
//
// ffmpeg -f lavfi -i color=c=green:s=16x16:r=1:d=1 -frames:v 1 -an
// -c:v libx265 -tag:v hvc1 -pix_fmt yuv420p -preset ultrafast
// -x265-params log-level=error:info=0 -map_metadata -1 -movflags +faststart
// h265.mp4.
func H265MP4() []byte {
	return decodeFixture(h265MP4Base64)
}

// VP9MP4 returns a 16x16 blue VP9 MP4 fixture. SHA-256:
// af5eeff8d624378f43cea29b8ef33649fbcfa4fd9e8600674a206d9c12620fda
//
// ffmpeg -f lavfi -i color=c=blue:s=16x16:r=1:d=1 -frames:v 1 -an
// -c:v libvpx-vp9 -lossless 1 -deadline best -cpu-used 0 -row-mt 0
// -map_metadata -1 -movflags +faststart vp9.mp4.
func VP9MP4() []byte {
	return decodeFixture(vp9MP4Base64)
}

// AV1MP4 returns a 64x64 yellow AV1 MP4 fixture. SHA-256:
// 70360fe0090fcc26bed290c1d75725ee0483478b56f674282032fcc7d4fbbce8
//
// ffmpeg -f lavfi -i color=c=yellow:s=64x64:r=1:d=1 -frames:v 1 -an
// -c:v libsvtav1 -preset 13 -crf 63 -pix_fmt yuv420p -map_metadata -1
// -movflags +faststart av1.mp4.
func AV1MP4() []byte {
	return decodeFixture(av1MP4Base64)
}

// H264AACMP4 returns a synthetic 30x18 H.264 MP4 with mono AAC audio.
// SHA-256: 820b312b9a2f20f277b833a8927ebfb272d25c8403191c4d56e8088c7948aace
//
// ffmpeg -f lavfi -i color=c=gray:s=30x18:r=25:d=5 -f lavfi
// -i anullsrc=r=48000:cl=mono -t 5 -map 0:v:0 -map 1:a:0
// -c:v libx264 -profile:v baseline -pix_fmt yuv420p -preset veryslow
// -crf 30 -c:a aac -ar 48000 -ac 1 -map_metadata -1 -movflags +faststart
// -f mp4 h264aac.mp4.
func H264AACMP4() []byte {
	return decodeFixture(h264AACMP4Base64)
}

// H264LongMP4 returns a synthetic one-frame H.264 MP4 with a 301-second
// sample duration. SHA-256:
// 591e184525618f3b2039aed7887addb09790f50b63e2e2359628c67502c55cc1.
//
// ffmpeg -f lavfi -i color=c=gray:s=16x16:r=1/301:d=301 -frames:v 1
// -c:v libx264 -profile:v baseline -pix_fmt yuv420p -preset veryslow
// -bsf:v filter_units=remove_types=6 -map_metadata -1 -fflags +bitexact
// -flags:v +bitexact -movflags +faststart -f mp4 h264long.mp4
func H264LongMP4() []byte {
	return decodeFixture(h264LongMP4Base64)
}

// H264WideMP4 returns a synthetic 1936x1088 H.264 MP4. SHA-256:
// cfd96d0511bb579f4f2baae72315efda82aba1a612caae6a25d382542003b3ae.
//
// ffmpeg -f lavfi -i color=c=gray:s=1936x1088:r=1:d=1 -frames:v 1
// -c:v libx264 -profile:v baseline -pix_fmt yuv420p -preset veryslow
// -crf 51 -bsf:v filter_units=remove_types=6 -map_metadata -1
// -fflags +bitexact -flags:v +bitexact -movflags +faststart -f mp4
// h264wide.mp4.
func H264WideMP4() []byte {
	return decodeFixture(h264WideMP4Base64)
}

// MP3 returns a 50 ms silent MPEG-1 Layer III fixture without metadata tags.
// SHA-256: 17944e919ea30c51a87c9c849e80ef9dcfda166cd275d0d448ab63b3ae9b95dc
//
// ffmpeg -f lavfi -i anullsrc=r=44100:cl=mono -t 0.05 -c:a libmp3lame
// -b:a 32k -write_xing 0 -id3v2_version 0 -map_metadata -1 -f mp3 sample.mp3
func MP3() []byte {
	return decodeFixture(mp3Base64)
}

func decodeFixture(encoded string) []byte {
	data, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		panic(err)
	}
	return data
}

const h264MOVBase64 = ""

const h265MP4Base64 = ""

const vp9MP4Base64 = ""

const av1MP4Base64 = ""

const mp3Base64 = ""

const h264AACMP4Base64 = ""

const h264LongMP4Base64 = ""

const h264WideMP4Base64 = ""
